{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "HIGH",
      "explanation": "Access logging is not enabled for the S3 bucket. Without access logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured. This increases the risk of accidental public exposure of sensitive data."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration. Without lifecycle rules, old or unused objects may accumulate, increasing storage costs and management overhead."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }

  force_destroy = true

  logging {
    target_bucket = "${local.resource_prefix.value}-access-logs"
    target_prefix = "${local.resource_prefix.value}/"
  }

  lifecycle_rule {
    enabled = true

    expiration {
      days = 365
    }

    noncurrent_version_expiration {
      days = 30
    }
  }

  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Enabled access logging for the S3 bucket to track access patterns. Added a Public Access block to prevent accidental public exposure. Configured a lifecycle rule to manage object expiration and reduce storage costs."
}
